// Host-owned registry of TerminalSurfaceDescriptor records (XH1).
//
// One immutable descriptor per reviewed terminal adapter id. The
// registry is read at `invoke()` time by the generic external-CLI
// launcher to pick a compatible surface. Adding a new terminal means
// ADDING a new entry here AND wiring the actual adapter in the host
// service — never editing a harness policy or a manifest.
//
// The descriptors are hand-curated from observed adapter behavior;
// they are NOT generated by reading the adapter's transport contract
// (which talks about operations, not user-facing capabilities). The
// audit trail is the commit that adds the entry.

import { TERMINAL_SURFACE_OPERATIONS } from "../../src/core/terminal-surface-contract.ts";

// Inline, hand-checked mirrors of the TypeScript contract — kept
// here so a failing test is observable from the host without a
// transpile step.
const DESCRIPTOR = {
  contractVersion: 1,
  adapterId: "ghostty",
  platform: "macos",
  supportedOperations: [...TERMINAL_SURFACE_OPERATIONS],
  capabilities: [
    "command",
    "environment",
    "cwd",
    "send-input",
    "lifecycle-events",
    // Ghostty 1.3.1 has no AppleScript command-events; we synthesize
    // them by polling terminal title. Treat as lifecycle-only.
  ],
  feedbackChannel: "polling",
};

const DESCRIPTOR_ITERM2 = {
  contractVersion: 1,
  adapterId: "iterm2",
  platform: "macos",
  supportedOperations: [...TERMINAL_SURFACE_OPERATIONS],
  capabilities: [
    "command",
    "environment",
    "cwd",
    "send-input",
    "lifecycle-events",
    "command-events",
    "multiplexer",
    "adopt-existing",
  ],
  feedbackChannel: "event-stream",
};

const DESCRIPTOR_IN_MEMORY = {
  contractVersion: 1,
  adapterId: "in-memory",
  platform: "macos", // tests run on the dev mac; irrelevant for the in-memory driver
  supportedOperations: [...TERMINAL_SURFACE_OPERATIONS],
  capabilities: [
    "command",
    "environment",
    "cwd",
    "lifecycle-events",
    "command-events",
  ],
  feedbackChannel: "event-stream",
};

const KNOWN_DESCRIPTORS = [DESCRIPTOR, DESCRIPTOR_ITERM2, DESCRIPTOR_IN_MEMORY];

function isTerminalSurfaceDescriptor(value) {
  if (value === null || typeof value !== "object" || Array.isArray(value)) return false;
  if (value.contractVersion !== 1) return false;
  if (typeof value.adapterId !== "string" || value.adapterId.length === 0) return false;
  if (!["macos", "linux", "windows"].includes(value.platform)) return false;
  if (!Array.isArray(value.supportedOperations)) return false;
  const OPS = new Set(TERMINAL_SURFACE_OPERATIONS);
  if (!value.supportedOperations.every((op) => typeof op === "string" && OPS.has(op))) return false;
  if (new Set(value.supportedOperations).size !== value.supportedOperations.length) return false;
  if (!Array.isArray(value.capabilities)) return false;
  const CAPS = new Set([
    "command", "environment", "cwd", "send-input",
    "lifecycle-events", "command-events", "screen-stream",
    "multiplexer", "adopt-existing",
  ]);
  if (!value.capabilities.every((c) => typeof c === "string" && CAPS.has(c))) return false;
  if (new Set(value.capabilities).size !== value.capabilities.length) return false;
  if (!["event-stream", "polling", "observation", "none"].includes(value.feedbackChannel)) return false;
  return true;
}

// Validate at module load — fail loud if a reviewer added a bad entry.
for (const desc of KNOWN_DESCRIPTORS) {
  if (!isTerminalSurfaceDescriptor(desc)) {
    throw new Error(`terminal-surface-registry: bad descriptor ${JSON.stringify(desc)}`);
  }
}

const BY_ADAPTER_ID = new Map(KNOWN_DESCRIPTORS.map((d) => [d.adapterId, d]));

/**
 * Look up a descriptor by reviewed adapter id. Returns null when the
 * adapter is unknown to the host.
 */
export function getTerminalSurfaceDescriptor(adapterId) {
  if (typeof adapterId !== "string") return null;
  return BY_ADAPTER_ID.get(adapterId) ?? null;
}

/**
 * All known descriptors (read-only snapshot). Returned in stable
 * declaration order so the policy module's picker is deterministic.
 */
export function listTerminalSurfaceDescriptors() {
  return [...KNOWN_DESCRIPTORS];
}

/**
 * Pure compatibility check (mirrors `terminalSurfaceSatisfies`).
 */
export function terminalSurfaceSatisfies(descriptor, requirements) {
  if (!isTerminalSurfaceDescriptor(descriptor)) return false;
  if (!Array.isArray(requirements)) return false;
  const have = new Set(descriptor.capabilities);
  return requirements.every((req) => have.has(req));
}

/**
 * Pick the first descriptor that satisfies a policy's terminal
 * requirements, preferring the supplied preferred-adapter order.
 * Returns null when nothing matches.
 */
export function pickCompatibleSurface(requirements, { preferred = [] } = {}) {
  const order = [
    ...preferred.filter((id) => BY_ADAPTER_ID.has(id)),
    ...KNOWN_DESCRIPTORS.map((d) => d.adapterId).filter((id) => !preferred.includes(id)),
  ];
  for (const id of order) {
    const desc = BY_ADAPTER_ID.get(id);
    if (terminalSurfaceSatisfies(desc, requirements)) return desc;
  }
  return null;
}

export {
  isTerminalSurfaceDescriptor,
  DESCRIPTOR as DESCRIPTOR_GHOSTTY,
  DESCRIPTOR_ITERM2 as DESCRIPTOR_ITERM2,
  DESCRIPTOR_IN_MEMORY as DESCRIPTOR_IN_MEMORY,
};
